from pathlib import Path
import json
P=Path('/tmp/pr-efficient1900');R=Path('/tmp/integer-mult-efficient1100-20261015')
receipt=json.loads((P/'check-archive-intake.json').read_text());ledger=json.loads((R/'docs/research/pr-ledger.json').read_text());prior={x['number']:x for x in ledger['pull_requests']};holds=json.loads((P/'review-holds.json').read_text());ready=json.loads((P/'ready-scopes.json').read_text());archives={}
for row in receipt['pull_requests']:
 if row['status']!='archive_intake_pass':continue
 n=row['number'];assert str(n) not in ready
 remaining=holds.get(str(n),{}).get('question') or prior.get(n,{}).get('unresolved_question') or 'Complete independent mathematical and source-bound reproduction review before scientific reliance or selected-frontier adoption.'
 scope='ARCHIVE ONLY — exact author source retained; new research-only paths, syntax and available manifest pins checked. No submitted code executed in this intake; stored PASS receipts and mathematical/κ claims remain author-supplied. Prior scoped checks remain available but do not complete whole-PR review.'
 archives[str(n)]=dict(head=row['head'],paths=row['paths'],scope=scope,remaining=remaining,source_receipt='research/community-efficient1900-audit/checks/check-archive-intake.json')
 ready[str(n)]=scope
(P/'archive-intake.json').write_text(json.dumps(archives,indent=2)+'\n');(P/'ready-scopes.json').write_text(json.dumps(ready,indent=2)+'\n');(P/'ready.json').write_text(json.dumps(sorted(map(int,ready)),indent=2)+'\n')
lines=['# Research archive intake and verification status','','Research packages listed here are accepted for preservation and collaboration. **Archival acceptance is not mathematical approval, an independent replay, or a selected-frontier update.** Original source and contributor attribution are retained. The central [PR ledger](pr-ledger.md) keeps these submissions `partially_reviewed`, including after GitHub marks them merged. Their remaining obligations are recorded below.','','## Review lanes','','- **Archive intake:** new isolated research paths only; authenticate exact author Git blobs/modes, full changed-file inventory, syntax and available local manifest pins. No execution of submitted code is implied. Historical author evidence stays attributed as such.','- **Validated research:** targeted mechanism/proof review and required source-bound checks completed within a stated scope.','- **Shared tooling:** review changed behavior and affected consumers before integrating. Archive intake cannot approve production changes.','- **Selected frontier:** complete applicable supplier/outer replay and mathematical review with inherited assumptions explicit. Only `certificates/selected-result.json` selects the result.','','Known counterexamples, misleading scope and unresolved changes to shared code stay out of this archive lane. A failed search is not an impossibility theorem. An archive claim may be wrong; verify it before relying on it. Prior expensive-check timeouts remain open obligations, not negative mathematical results.','','## Efficient queue procedure','','Freeze 100 PR heads; compare against the ledger before reading bodies or rerunning checks. Reuse authenticated evidence only for identical sources and covered obligations. Group related construction chains and audit the strongest relevant descendant for frontier consideration, crediting covered predecessors. Merge cleared archive groups independently of expensive verification. A merged archive is complete for intake, but its scientific review remains open. Check the live head immediately before integration.','','No author workload was run for this intake. Local expensive verification remains serial under the sampled 1 GiB descendant-process watchdog, with explicit time limits and no unchanged automatic retries after resource stops. No Lean or Docker was run. Remote CI, if triggered by publication, is separate evidence and is not represented as a local pass.','','## Exact-head archive index','','Publication state is authoritative in the [central ledger](pr-ledger.json) and [round dispositions](../../research/community-efficient1900-audit/DISPOSITIONS.json). This index also lists approved intake awaiting publication.','','| PR / contributor | Source head | Retained package(s) | Remaining independent review |','| --- | --- | --- | --- |']
credits=['','## Source-only research archive contributions','','The following contributions were accepted through source-only archival intake. This preserves authorship and predecessor notices without endorsing the mathematical claims or advertised κ. See [review status](docs/research/research-archive-intake.md) for outstanding obligations.','']
for key,a in archives.items():
 n=int(key);m=json.loads((P/f'{n}.json').read_text());author=m['author'].get('name') or m['author']['login'];login=m['author']['login'];url=m['url'];paths=', '.join('`'+x+'`' for x in a['paths'])
 lines.append(f'| [#{n}]({url}) — {author} (@{login}) | `{a["head"]}` | {paths} | {a["remaining"].replace("|","/")} |')
 credits.append(f'- **{author} (@{login})** — [#{n}]({url}): {m["title"]}. Archived with original predecessor credit; independent full-claim review remains open.')
(R/'docs/research/research-archive-intake.md').write_text('\n'.join(lines)+'\n')
f=R/'CONTRIBUTORS.md';s=f.read_text();assert '## Source-only research archive contributions' not in s;f.write_text(s.rstrip()+'\n'+'\n'.join(credits)+'\n')
print('Registered',len(archives),'archive-only submissions; scientific completion flags remain false.')
